#!/usr/bin/env node
const NINTH_ORIGINAL_URL=new URL("../../../../../agent-evaluation/verify-agent-evaluation.mjs",import.meta.url);
import {eighthLeaf,eighthQuestion,eighthIncludes} from '../eighth-reconciliation/verify-dependencies.mjs';
// Final-only, read-only acceptance. No overlay, candidate mode, fallback data or project imports.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(NINTH_ORIGINAL_URL));assert.deepEqual(process.argv.slice(2).filter(x=>x.startsWith('--')),['--dist'],'Only --dist is accepted; no candidate or overlay mode');const at=process.argv.indexOf('--dist');assert.ok(at>=0&&process.argv[at+1],'--dist must name the actual final dist');const dist=path.resolve(process.argv[at+1]),read=n=>JSON.parse(fs.readFileSync(path.join(here,n),'utf8')),sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const pkg=read('records.json'),app=read('append-manifest.json'),identity=read('identity-baseline.json'),map=read('preservation-map.json'),variants=read('variant-map.json'),sections=read('sections.json');const E=new Map();for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(x=>x.endsWith('.json')))for(const e of JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f))).entries){assert.ok(!E.has(e.id));E.set(e.id,e);}
const get=key=>{const [id,q]=key.split('#');const e=E.get(id);assert.ok(e,`Missing entry ${id}`);if(q===undefined)return e;const x=e.items?.find((x,i)=>String(x.id??i)===q);assert.ok(x,`Missing question ${key}`);return x;},field=(e,p)=>p.reduce((v,k)=>v[k],e),decode=s=>s.replaceAll('&quot;','"').replaceAll('&#39;',"'").replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&amp;','&'),txt=s=>decode(s.replace(/<[^>]+>/g,'')),blocks=s=>[...s.matchAll(/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g)],unfold=s=>s.replace(/<details\b[\s\S]*?<\/details>/g,'');
const dest=d=>{assert.equal(sha(d.html),d.sha256);const s=get(d.stableReviewKey).a;for(const f of d.fragments||[d.html])assert.ok(eighthIncludes(d.stableReviewKey.split('#')[0],['items',get(d.stableReviewKey.split('#')[0]).items.indexOf(get(d.stableReviewKey)),'a'],s,f),`Substantive destination drift: ${d.stableReviewKey} / ${d.section}`);assert.ok(txt(d.html).length>=40,'A title or link alone is not substantive coverage');};
const balanced=s=>{const st=[],voids=new Set(['br','hr','img','wbr']);for(const m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){const tag=m[2].toLowerCase();if(m[1])assert.equal(st.pop(),tag,`Unbalanced ${tag}`);else if(!voids.has(tag)&&!m[0].endsWith('/>'))st.push(tag);}assert.deepEqual(st,[]);};
const checks=[];const check=(name,fn)=>{try{checks.push({name,status:'passed',...fn()});}catch(e){checks.push({name,status:'failed',error:e.message});}};
check('two-exact-final-leaves',()=>{assert.equal(pkg.records.length,2);for(const r of pkg.records){assert.equal(r.entryId,'ai-agent-9');assert.ok(['a','lead'].includes(r.path[2]));assert.equal(r.path[1],6);assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);assert.equal(field(get(r.entryId),r.path),eighthLeaf(r.entryId,r.path,r.after),`Unapplied or drifted ${r.entryId}/${r.path.join('/')}`);}return {alreadyApplied:2,stagedInMemory:0,siteWrites:0};});
check('six-stable-appends-at-15-through-20',()=>{assert.equal(app.additions.length,6);for(const [i,a]of app.additions.entries()){assert.equal(a.expectedIndex,15+i);assert.equal(a.expectedOldCount,15);assert.equal(a.order,1000001+i);const e=get(a.entryId),x=get(a.entryId+'#'+a.questionId);assert.equal(e.items.indexOf(x),a.expectedIndex);assert.deepEqual(x,a.expectedItem);assert.equal(sha(x.a),a.afterSha256);}return {appends:6};});
check('fifteen-old-identities-and-progress-unchanged',()=>{const e=get('ai-agent-9');assert.equal(e.items.length,21);assert.deepEqual(Object.fromEntries(Object.entries(e).filter(([k])=>!['items','number'].includes(k))),identity.entryFields);assert.equal(e.number,'21 问');for(let i=0;i<15;i++)assert.deepEqual(Object.fromEntries(Object.entries(e.items[i]).filter(([k])=>!['a','lead'].includes(k))),identity.identities[i]);return {oldIdentities:15};});
check('fourteen-other-answers-including-protected-skill-unchanged',()=>{const e=get('ai-agent-9');for(let i=0;i<15;i++)if(i!==6)assert.deepEqual(e.items[i],eighthQuestion('ai-agent-9',i,identity.oldItems[i]));assert.equal(sha(e.items[8].a),identity.bodySha256s[8]);return {untouchedOldAnswers:14,protectedSkillIndex:8};});
check('all222-original-blocks-have-substantive-destinations',()=>{const r=pkg.records.find(r=>r.path[2]==='a'),bs=blocks(r.before);assert.equal(map.sourceBlockCount,222);assert.equal(bs.length,222);assert.equal(map.blocks.length,222);assert.equal(map.beforeSha256,sha(r.before));assert.equal(map.afterSha256,sha(r.after));for(const [i,b]of map.blocks.entries()){assert.equal(b.sourceBlockIndex,i);assert.equal(b.sourceHtml,bs[i][0]);assert.equal(sha(b.sourceHtml),b.sourceSha256);assert.equal(Array.from(r.before).slice(...b.sourceSpanCodePoints).join(''),b.sourceHtml);assert.ok(b.destinations.length>0);for(const d of b.destinations)dest(d);}return {mappedBlocks:222};});
check('all119-plus34-folded-wordings-retained-with-links',()=>{const body=get('ai-agent-9#q-ai-agent-eval-run').a;assert.equal(variants.originalQaVariantCount,119);assert.equal(variants.originalInterviewVariantCount,34);assert.equal(variants.variants.length,153);for(const cls of ['qa-variants','interview-variants']){const old=variants.variants.filter(v=>v.fold===cls),fold=body.match(new RegExp('<details class="'+cls+'">[\\s\\S]*?<\\/details>'))?.[0];assert.ok(fold,cls);const vs=[...fold.matchAll(/<(p|li)\b[^>]*>([\s\S]*?)<\/\1>/g)].map(x=>({text:txt(x[0]),html:x[0]}));assert.equal(vs.length,old.length);assert.deepEqual(vs.map(x=>x.text).sort(),old.map(x=>x.original).sort());for(const v of old){assert.equal(sha(v.sourceHtml),v.sourceSha256);assert.ok(vs.some(x=>x.text===v.original&&x.html.includes('href="#/e/')));v.destinations.forEach(dest);}}for(const s of variants.commonPhrasings)assert.ok(txt(body).includes(s));return {qaVariants:119,interviewVariants:34,commonPhrasings:2};});
check('unique-topic-details-live-in-their-substantive-answers',()=>{const main=unfold(get('ai-agent-9#q-ai-agent-eval-run').a);const pairs=[['q-ai-agent-eval-longdoc',['跨页表格','续表关系','无答案','保留集']],['q-ai-agent-eval-tool-evidence',['临时生成','缺失结果','测试确实要求不同答案','有效对照对数']],['q-ai-agent-eval-parameter-attribution',['模型输出、宿主规范化、实际发送和工具接收','9007199254740993','精确十进制','未知效果另报']],['q-ai-agent-eval-replay-environment',['不能重放生产写操作','请求语义匹配','状态型模拟器','用户模拟器','不能只靠seed消除']],['q-ai-agent-eval-business-acceptance',['过敏','用户没回复不等于满意','回执丢失','未知效果']],['q-ai-agent-eval-trace-attribution',['Top 10','不足十条','私有思维链','双人独立标注','多因和未知','日志分页数','失败及截断任务']]];for(const [id,terms] of pairs){const a=get('ai-agent-9#'+id).a;for(const term of terms)assert.ok(a.includes(term),`${id}: ${term}`);assert.ok(a.length>800);}
for(const distinctive of ['跨页表格要带表头','临时生成的订单状态','模型输出、宿主规范化、实际发送和工具接收','并行系统需记录实际因果关系','有过敏等重要限制时','先按task/run/step/attempt'])assert.ok(!main.includes(distinctive),'Unique detailed body duplicated in main: '+distinctive);return {independentAnswers:6};});
check('main-answer-keeps-case-run-grader-isolation-and-sample-boundaries',()=>{const main=unfold(get('ai-agent-9#q-ai-agent-eval-run').a);for(const t of ['Case','Run','Grader','业务时钟','真','允许动作','完整保留用例集','隐藏的是数据与答案','不能代替执行权限','工作区和资源预算','不能临时删除失败题','UNKNOWN','20 个真实 Case 各跑 3 轮','60 次运行，不是 60 个独立业务场景','固定 20% 留出','分子分母','ASR 字错率','同 operationId 不再写','同版本内容不可偷偷改变'])assert.ok(main.includes(t),t);assert.ok(!/原题中|迁移到|更正为|来自原题/.test(main));assert.ok(txt(main).length>1500);return {completeOralAnswer:true};});
check('html-and-stable-routes-resolve-with-no-anchor-loss',()=>{let n=0;for(const s of [...pkg.records.map(r=>r.after),...app.additions.map(a=>a.expectedItem.a)]){balanced(s);assert.ok(!/<(?:script|style|iframe|pre)\b/i.test(s));for(const m of s.matchAll(/href="#\/e\/([^"/]+)(?:\/([^"/]+))?"/g)){get(decodeURIComponent(m[1])+(m[2]?'#'+decodeURIComponent(m[2]):''));n++;}}for(const r of pkg.records)for(const m of r.before.matchAll(/\bid="([^"]+)"/g))assert.ok(r.after.includes(`id="${m[1]}"`));return {resolvedRoutes:n};});
check('numeric-example-is-exact-and-repeated-runs-not-independent-cases',()=>{const id='9007199254740993';assert.equal(BigInt(id),9007199254740993n);assert.notEqual(BigInt(Number(id)),BigInt(id));assert.equal(JSON.parse(JSON.stringify({id})).id,id);assert.equal(20*3,60);return {caseFamilies:20,runs:60,numericStringRoundTrip:true,scope:'Small arithmetic and serialization fixture only; no model performance experiment'};});
const report={mode:'final',dist,recordsSha256:sha(fs.readFileSync(path.join(here,'records.json'))),verifierSha256:sha(fs.readFileSync(fileURLToPath(import.meta.url))),passed:checks.filter(x=>x.status==='passed').length,failed:checks.filter(x=>x.status==='failed').length,total:checks.length,siteWrites:0,stagedInMemory:0,actualFinalDistAcceptance:checks.every(x=>x.status==='passed'),checks,limitations:['No build, rendering or model run is performed.','Only the actual --dist path is read; missing or unapplied content fails.']};console.log(JSON.stringify(report,null,2));if(report.failed)process.exitCode=1;
